class Solution {
public:
    int maxLengthBetweenEqualCharacters(string s) {
        int first[26], last[26];
        for (int i = 0; i < 26; i++) {
            first[i] = -1;
            last[i] = -1;
        }
        for (int i = 0; i < (int)s.size(); i++) {
            int c = s[i] - 'a';
            if (first[c] == -1) first[c] = i;
            last[c] = i;
        }
        int ans = -1;
        for (int i = 0; i < 26; i++) {
            if (first[i] != -1 && last[i] != first[i]) {
                ans = max(ans, last[i] - first[i] - 1);
            }
        }
        return ans;
    }
};
